  "model": "synthetic-garden-v2",
  "date": "2025-04-07",
  "units": "KPI units (contributions section)",
  "components": {"Base": 80, "Leaf Activity": 36, "Seed Activity": 36, "Weather": -7, "Overlap": -5, "Model": 140},
  "reconciliation": {
    "sum_before_overlap": "80 + 36 + 36 + (-7) = 145",
    "model": 140,
    "residual_before_overlap": "Model - sum_before_overlap = 140 - 145 = -5",
    "overlap": -5,
    "check": "145 + (-5) = 140 = Model, so the residual is fully accounted for by Overlap"
  },
  "overlap_interpretation": {
    "is_media_channel_loss": false,
    "explanation": "The model uses a log link with removal_lift attribution. Under that setup, Overlap is a reconciliation term. It makes the separately computed removal-lift components add up to the fitted Model total. It can be positive or negative. Here the components sum to 5 more than Model, so Overlap is −5. It is not a media channel, has no spend or ROI, and should not be ranked, given a share, or optimised. Leaf Activity and Seed Activity (36 each) are the media channels, and neither is reduced by Overlap. The −5 reflects how the multiplicative effects interact under removal_lift; it does not show that either channel lost sales."
