  "weather_reference": {
    "control_reference": {"resolved": "mean", "q_ref": 12},
    "explanation": "Weather's contribution is measured relative to its reference level, the mean, with q_ref = 12. The −7 means Weather was below that reference in effect on this date. It does not mean Weather removed 7 units from an absolute zero. The sign and size depend on the reference choice. A different reference would shift Weather and the Base/Overlap split, though it would not change Model. Weather is a retained control, not media. Its signed effect does not identify the raw weather input or a unique cause."
  },
  "additional_config": {"link": "log", "attribution": "removal_lift", "multiplier": 5, "note": "The multiplier of 5 is in the config. Contributions are reported in KPI units and were not converted to revenue here."}
